#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Publishes Unpaged for Android on Google Play: account, Google Cloud access for
# play/publish.sh, the app entry, policy declarations, the 14-day closed test and
# production. Re-run any time; captured values live in ~/.config/unpaged/play.env.

TOTAL_STAGES=14

CONFIG="$HOME/.config/unpaged"
ENV_FILE="$CONFIG/play.env"
HERE="$(cd "$(dirname "$0")" && pwd)"
ANDROID="$(cd "$HERE/.." && pwd)"
AAB="$ANDROID/app/build/outputs/bundle/release/app-release.aab"
ASSETS="$CONFIG/play-assets"
CONSOLE="https://play.google.com/console"
mkdir -p "$CONFIG" && chmod 700 "$CONFIG"

# Keep provisioning callable on its own for checks with a temporary CONFIG.
create_upload_key() (
  local service="${1:-Unpaged Play upload key}" password developer_name store_file
  if [[ -e "$CONFIG/unpaged-upload.jks" ]]; then
    warn "The upload keystore already exists; refusing to replace it."
    exit 1
  fi
  umask 077
  mkdir -p "$CONFIG"
  ask developer_name "Developer name [Andrei Baluta]:"
  developer_name="${developer_name:-Andrei Baluta}"
  # Quote the CN so commas in a developer name do not become DN separators.
  developer_name="${developer_name//\\/\\\\}"
  developer_name="${developer_name//\"/\\\"}"
  password="$(openssl rand -base64 24)"
  security add-generic-password -U -a "$USER" -s "$service" -w "$password"
  JAVA_HOME=/opt/homebrew/opt/openjdk@21
  "$JAVA_HOME/bin/keytool" -genkeypair -v -keystore "$CONFIG/unpaged-upload.jks" \
    -storetype PKCS12 -alias upload -keyalg RSA -keysize 4096 -validity 10000 \
    -storepass "$password" -keypass "$password" -dname "CN=\"$developer_name\""
  store_file="${CONFIG//\\/\\\\}/unpaged-upload.jks"
  printf 'storeFile=%s\nstorePassword=%s\nkeyAlias=upload\nkeyPassword=%s\n' \
    "$store_file" "$password" "$password" > "$CONFIG/upload-signing.properties"
  chmod 600 "$CONFIG/upload-signing.properties" "$CONFIG/unpaged-upload.jks"
  say "Created the upload key and signing properties; saved its password in Keychain."
)

banner "Unpaged for Android → Google Play"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Google Play developer account"
say "Create a personal developer account. It costs US\$25 once."
open_url "https://play.google.com/console/signup"
step "Sign in with the Google account that should own Unpaged."
step "Choose an account for yourself (personal), not an organization."
step "Developer name: Andrei Baluta (this name is shown on Google Play)."
step "Fill in contact email/phone and developer email; verify each with its one-time code."
step "Pay the registration fee and finish identity verification. It can take a few days."
step "Do every task the Play Console home page lists for the account itself"
step "  (for example, verifying an Android phone with the Play Console app)."
note "The account page URL looks like $CONSOLE/u/0/developers/<number>/…"
ask PLAY_DEVELOPER_ID "Developer account number from that URL:"
write_env PLAY_DEVELOPER_ID "$PLAY_DEVELOPER_ID"
pause "Press Enter once Play Console shows your account home page."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Back up the upload key"
if [[ -e "$CONFIG/unpaged-upload.jks" && ! -f "$CONFIG/upload-signing.properties" ]]; then
  warn "The upload key exists, but upload-signing.properties is missing. Keep the existing key."
  step "Recreate $CONFIG/upload-signing.properties with storeFile=$CONFIG/unpaged-upload.jks,"
  step "keyAlias=upload, and storePassword/keyPassword set to the existing Keychain password."
  note "Retrieve it with: security find-generic-password -a '$USER' -s 'Unpaged Play upload key' -w"
  step "Run chmod 600 on the properties file and keystore, then re-run stage 2."
  exit 1
elif [[ ! -f "$CONFIG/unpaged-upload.jks" || ! -f "$CONFIG/upload-signing.properties" ]]; then
  warn "The upload key or signing properties are missing."
  confirm "Create a new upload key and signing properties on this Mac?" || exit 1
  create_upload_key
fi
say "Every Play update must be signed with this key. If it's lost, Google can"
say "reset it, but only after a support request. Keep two copies."
step "Keystore file: $CONFIG/unpaged-upload.jks"
step "Its password is in the macOS Keychain item \"Unpaged Play upload key\"."
note "Show it with: security find-generic-password -s 'Unpaged Play upload key' -w"
step "Save the file and the password in your password manager (or another safe place off this Mac)."
open -R "$CONFIG/unpaged-upload.jks" 2>/dev/null || true
confirm "Is the keystore and its password backed up?" || warn "Back it up before the first upload."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: publishing access for play/publish.sh"
say "publish.sh uploads builds and the store listing through the Play API. It acts"
say "as a service account that your own gcloud login impersonates, so no key file exists."
command -v gcloud >/dev/null 2>&1 || { warn "Install it first: brew install --cask google-cloud-sdk"; exit 1; }
if [[ -z "$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null)" ]]; then
  step "A browser opens: sign in with the same Google account and allow access."
  gcloud auth login
fi
GCLOUD_ACCOUNT="$(gcloud auth list --filter=status:ACTIVE --format='value(account)' | head -1)"
say "Signed in to gcloud as $GCLOUD_ACCOUNT"
note "Project IDs are global. Lowercase letters, digits and hyphens, 6-30 characters."
current_project="$(_existing PLAY_GCP_PROJECT || true)"
[[ -n "$current_project" ]] || write_env PLAY_GCP_PROJECT "unpaged-play-$(LC_ALL=C tr -dc 'a-z0-9' </dev/urandom | head -c 5 || true)"
ask PLAY_GCP_PROJECT "Google Cloud project ID:"
write_env PLAY_GCP_PROJECT "$PLAY_GCP_PROJECT"
SA="unpaged-play-publisher@$PLAY_GCP_PROJECT.iam.gserviceaccount.com"
if confirm "Create or reuse project $PLAY_GCP_PROJECT and service account $SA?"; then
  gcloud projects describe "$PLAY_GCP_PROJECT" >/dev/null 2>&1 \
    || gcloud projects create "$PLAY_GCP_PROJECT" --name="Unpaged Play" \
    || { warn "Project creation failed. New Cloud users must accept the terms once at"; \
         warn "https://console.cloud.google.com, or the ID is taken. Re-run this wizard."; exit 1; }
  gcloud services enable androidpublisher.googleapis.com iamcredentials.googleapis.com --project="$PLAY_GCP_PROJECT"
  gcloud iam service-accounts describe "$SA" --project="$PLAY_GCP_PROJECT" >/dev/null 2>&1 \
    || gcloud iam service-accounts create unpaged-play-publisher --project="$PLAY_GCP_PROJECT" \
         --display-name="Unpaged Play publisher"
  gcloud iam service-accounts add-iam-policy-binding "$SA" --project="$PLAY_GCP_PROJECT" \
    --member="user:$GCLOUD_ACCOUNT" --role=roles/iam.serviceAccountTokenCreator >/dev/null
  printf '%s\n' "$PLAY_GCP_PROJECT" > "$CONFIG/play-gcp-project"
  write_env PLAY_SERVICE_ACCOUNT "$SA"
  say "Done. Copy this email for stage 5: $SA"
else
  SKIPPED+=("Google Cloud project and service account (re-run stage 3)")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the app in Play Console"
open_url "$CONSOLE"
step "Home → Create app."
step "App name: $(cat "$HERE/listings/en-US/title.txt")"
step "Default language: English (United States) – en-US."
step "App or game: App.   Free or paid: Free."
step "Contact email: andrei.baluta@yahoo.com"
step "Tick the Developer Program Policies, US export laws and Play App Signing terms."
step "Click Create app."
note "The package name, app.unpaged, is set by the first upload in stage 6 and is permanent."
pause "Press Enter once the app's dashboard is open."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Let publish.sh act for you"
SA="$(_existing PLAY_SERVICE_ACCOUNT || echo "unpaged-play-publisher@<project>.iam.gserviceaccount.com")"
step "Play Console (account level, not inside the app): Users and permissions → Invite new users."
step "Email address: $SA"
step "Under App permissions → Add app → Unpaged. Allow releasing to testing tracks,"
step "  releasing to production and managing the store listing (Admin also works)."
step "Click Invite user, then confirm."
note "A service account accepts automatically. Access can take a few minutes to start working."
open_url "$CONSOLE"
pause "Press Enter once the service account is listed under Users and permissions."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First upload: internal testing"
say "Google requires the very first bundle to be uploaded by hand."
if [[ ! -f "$CONFIG/upload-signing.properties" || ! -f "$CONFIG/unpaged-upload.jks" ]]; then
  warn "Cannot build or upload: upload signing files are missing. Complete stage 2 first."
  exit 1
fi
JAVA_HOME=/opt/homebrew/opt/openjdk@21
if [[ ! -f "$AAB" ]] && confirm "No release bundle yet. Build it now with Gradle?"; then
  (cd "$ANDROID" && JAVA_HOME="$JAVA_HOME" \
    ANDROID_HOME="${ANDROID_HOME:-$HOME/Library/Android/sdk}" ./gradlew --no-daemon :app:bundleRelease)
fi
if [[ ! -f "$AAB" ]]; then
  warn "No release bundle exists. Build it in stage 6 before uploading."
  exit 1
fi
# jarsigner returns success for unsigned archives; require its verified result too.
if ! verification="$(LC_ALL=C "$JAVA_HOME/bin/jarsigner" -verify "$AAB" 2>&1)" \
  || ! grep -q '^jar verified\.$' <<< "$verification"; then
  warn "Release bundle is unsigned or its signature is invalid. Complete stage 2 and rebuild in stage 6."
  say "$verification"
  exit 1
fi
say "Signed bundle: $AAB"
open -R "$AAB" 2>/dev/null || true
step "In the app: Test and release → Testing → Internal testing → Testers tab:"
step "  Create email list \"Me\" with your own address, save, and tick it."
step "Releases tab → Create new release. Keep the Google-generated app signing key."
step "Drag app-release.aab into App bundles. Release name: 1.0.0 (1)."
step "Release notes: paste the text printed below."
step "Next → Save, then roll the release out to internal testing."
printf '\n%s\n\n' "$(cat "$HERE/release-notes/en-US/default.txt")"
open_url "$CONSOLE"
pause "Press Enter once the internal release is rolled out."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Store listing and store settings"
say "Uploading title, descriptions, icon, feature graphic and screenshots through the API."
if [[ -d "$ASSETS/phoneScreenshots" ]] && confirm "Run play/publish.sh listing now?"; then
  "$HERE/publish.sh" listing || warn "Upload failed. Check stage 5, wait a few minutes and re-run this stage."
else
  SKIPPED+=("Store listing upload: play/publish.sh listing (images in $ASSETS)")
fi
step "Grow users → Store presence → Store settings:"
step "  App category: Books & Reference. Add up to five tags (for example Audiobooks, Books)."
step "  Store listing contact details: website https://unpaged.app/support/"
step "Main store listing: check the text and images landed, then Save."
open_url "$CONSOLE"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "App content: privacy, ads, access"
say "Policy and programs → App content. Answer each section as follows:"
step "Privacy policy: https://unpaged.app/privacy/"
step "Ads: No, my app does not contain ads."
step "App access: All functionality is available without any access restrictions."
note "  Audiobookshelf connects to the user's own server, like a mail app's server; nothing is behind an Unpaged account."
step "Advertising ID: No (the app has no AD_ID permission)."
step "Government apps: No.  Financial features: none.  Health apps: none."
step "News apps: No."
open_url "$CONSOLE"
pause "Press Enter once these sections show as complete."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "App content: content rating"
step "App content → Content rating → Start questionnaire."
step "Email: andrei.baluta@yahoo.com.  Category: Reference, News, or Educational."
step "Answer for what the app itself shows. Suggested answers:"
step "  Violence, sexuality, language, drugs, gambling: No."
step "  Users interact or share content with each other: No."
step "  Shares the user's location: No.   Digital purchases: No."
note "LibriVox books are public-domain classics the user chooses to play; the app has no chat, sharing or store."
step "Save → Next → Submit."
open_url "$CONSOLE"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "App content: target audience and data safety"
step "Target audience: 13-15, 16-17 and 18 and over. Not designed for children."
step "  \"Could the app unintentionally appeal to children?\" No."
step "Data safety:"
step "  Collects or shares required data types? Yes."
step "  All data encrypted in transit? Yes.   Account creation: users can't create an account."
step "  Data types (from Google ML Kit, used by on-device AI):"
step "    App info and performance → Diagnostics."
step "    Device or other IDs → Device or other IDs."
step "  For each: Collected, not shared; not processed ephemerally; required (users can't turn it off);"
step "    purpose Analytics."
note "Imported audio, moments, progress and Audiobookshelf credentials stay on the phone or go to"
note "the user's own server, so they aren't declared. The privacy policy says the same."
open_url "https://developers.google.com/ml-kit/android-data-disclosure"
open_url "$CONSOLE"
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Foreground services and demo videos"
say "Android 14+ apps must justify each foreground service type with a video."
step "Upload both videos to YouTube as Unlisted:"
step "  $ASSETS/fgs-playback.mp4"
step "  $ASSETS/fgs-download.mp4"
open -R "$ASSETS/fgs-playback.mp4" 2>/dev/null || true
open_url "https://studio.youtube.com"
ask PLAY_FGS_PLAYBACK_VIDEO "YouTube link for fgs-playback.mp4:"
write_env PLAY_FGS_PLAYBACK_VIDEO "$PLAY_FGS_PLAYBACK_VIDEO"
ask PLAY_FGS_DOWNLOAD_VIDEO "YouTube link for fgs-download.mp4:"
write_env PLAY_FGS_DOWNLOAD_VIDEO "$PLAY_FGS_DOWNLOAD_VIDEO"
step "App content → Foreground service permissions. Tick both types:"
step "  Media playback — use case: Media playback."
step "    Description: Plays audiobooks the user starts, and keeps playing with the screen off"
step "    or in another app, with controls in the notification, lock screen and Android Auto."
step "    Impact if delayed or interrupted: the audiobook stops mid-listen and the user loses their place."
step "    Video: $PLAY_FGS_PLAYBACK_VIDEO"
step "  Data sync — use case: Network transfer: upload or download."
step "    Description: Downloads a free LibriVox audiobook for offline listening after the user taps"
step "    Download Free Book; progress and a Cancel button show in the notification."
step "    Impact: the download pauses and resumes later; offline listening isn't ready when expected."
step "    Video: $PLAY_FGS_DOWNLOAD_VIDEO"
open_url "$CONSOLE"
pause "Press Enter once the declaration is saved."

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Closed test"
say "New personal accounts need 12 testers opted in for 14 days in a row before production."
step "Make a Google Group testers can join themselves, e.g. unpaged-testers@googlegroups.com"
step "  (groups.google.com → Create group → anyone can join)."
open_url "https://groups.google.com/my-groups"
ask PLAY_TESTER_GROUP "Google Group email:"
write_env PLAY_TESTER_GROUP "$PLAY_TESTER_GROUP"
step "Play Console → Test and release → Testing → Closed testing → Manage track (Alpha)."
step "Testers tab: Google Groups → $PLAY_TESTER_GROUP. Save."
step "Countries/regions tab: add the countries your testers are in."
step "Releases: Create new release → Add from library → 1.0.0 (1). Paste the same notes, Save."
step "Publishing overview → Send changes for review. The first closed release is reviewed (often a few days)."
open_url "$CONSOLE"
pause "Press Enter once it's sent for review."

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Recruit 12 testers for 14 days"
say "After review, Closed testing shows a \"Join on Android\" / web opt-in link."
ask PLAY_OPT_IN_URL "Opt-in link (Enter to skip until review passes):"
[[ -n "$PLAY_OPT_IN_URL" ]] && write_env PLAY_OPT_IN_URL "$PLAY_OPT_IN_URL"
step "Ask at least 12 people (aim for 15 or more) with Android phones to:"
step "  1. Join $PLAY_TESTER_GROUP with their Google account."
step "  2. Open the opt-in link, tap Become a tester, then install Unpaged from Google Play."
step "  3. Stay opted in for 14 days and actually use it: import a book, stream a classic, save a moment."
note "Leaving and rejoining restarts that tester's 14 days. Google checks real use, not just installs."
note "Collect their feedback: the production application asks what you learned and changed."
step "Ship fixes to the testers: raise versionCode, ./gradlew :app:bundleRelease, then play/publish.sh bundle alpha"
step "  and roll out the draft from Closed testing."
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Apply for production"
say "When the Dashboard shows the 14-day requirement met:"
step "Dashboard → Apply for production. Answer the three sections: About your closed test,"
step "  About your app, About your production readiness. Then Apply. Review is usually 7 days or less."
step "After approval: Test and release → Production → Countries/regions (add all you want),"
step "  then Create new release → Add from library (or play/publish.sh bundle production)."
step "Review release → Start rollout. A staged rollout (e.g. 20%) is safest for the first release."
note "Every later update: raise versionCode, bundleRelease, play/publish.sh bundle <track>."
open_url "$CONSOLE"
pause

finish
note "Values saved in $ENV_FILE. Store text lives in android/play/listings/ and play/publish.sh listing re-uploads it."
